// Entity representing a task in the database
@Entity
@Table(name = "tasks")
public record Task(
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    Long id,
    @Column(nullable = false)
    Long userId,
    String title,
    String description,
    boolean completed,
    LocalDateTime createdAt
) {}

@RestController
@RequestMapping("/api/tasks")
public class TaskController {
    private final TaskService taskService;

    @GetMapping
    public List<Task> getUserTasks(@AuthenticationPrincipal UserPrincipal user) {
        return taskService.findByUserId(user.getId()); // Only fetch tasks for logged-in user
    }

    @PostMapping
    public Task createTask(@RequestBody TaskRequest request, @AuthenticationPrincipal UserPrincipal user) {
        return taskService.create(request, user.getId());
    }

    @PutMapping("/{id}")
    public Task updateTask(@PathVariable Long id, @RequestBody TaskRequest request, @AuthenticationPrincipal UserPrincipal user) {
        return taskService.update(id, request, user.getId()); // Verify ownership before updating
    }

    @DeleteMapping("/{id}")
    public void deleteTask(@PathVariable Long id, @AuthenticationPrincipal UserPrincipal user) {
        taskService.delete(id, user.getId());
    }
}

@Repository
public interface TaskRepository extends JpaRepository<Task, Long> {
    List<Task> findByUserId(Long userId); // Custom query method for user-specific tasks
}

